def decode_ways(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    memo = {}

    def dp(i: int) -> int:
        if i == len(s):
            return 1
        if i in memo:
            return memo[i]

        res = 0

        # Single digit decoding
        if s[i] != '0':
            res += dp(i + 1)

        # Two digit decoding
        if i + 1 < len(s):
            two_digit = int(s[i:i+2])
            if 1 <= two_digit <= 26 and s[i] != '0':
                res += dp(i + 2)

        memo[i] = res
        return res

    return dp(0)
