from typing import List, Tuple

def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, +, -, *, / and parentheses.
    Supports normal operator precedence. Division is integer division truncating toward zero.
    Spaces may appear anywhere.
    """

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            # Parse number
            num_str = ''
            while i < len(expr) and expr[i].isdigit():
                num_str += expr[i]
                i += 1
            tokens.append(int(num_str))

    # Two-stack approach for evaluation (shunting-yard algorithm logic)
    # ops: stack of operators
    # vals: stack of values

    ops = []
    vals = []

    def peek_op():
        if not ops:
            return None
        return ops[-1]

    def pop_op():
        op = ops.pop()
        b = vals.pop()
        a = vals.pop()
        if op == '+':
            vals.append(a + b)
        elif op == '-':
            vals.append(a - b)
        elif op == '*':
            vals.append(a * b)
        elif op == '/':
            # Integer division truncating toward zero
            # Python's // operator floors for negative numbers, so we need manual handling
            res = a // b if (a > 0 and b > 0) or (a < 0 and b < 0) else -(abs(a) // abs(b))
            vals.append(res)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    for token in tokens:
        if isinstance(token, int):
            vals.append(token)
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                pop_op()
            ops.pop() # Pop '('
        else: # operator
            while (ops and ops[-1] != '(' and 
                   precedence(ops[-1]) >= precedence(token)):
                pop_op()
            ops.append(token)

    while ops:
        pop_op()

    return vals[0] if vals else 0
