def decode_ways(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    # dp[i] represents the number of ways to decode the substring s[0:i]
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: one way to decode an empty string

    for i in range(1, n + 1):
        # Check single digit decoding (s[i-1])
        if s[i-1] != '0':
            digit = int(s[i-1])
            if 1 <= digit <= 9:
                dp[i] += dp[i-1]

        # Check two digit decoding (s[i-2:i])
        if i >= 2:
            two_digit_str = s[i-2:i]
            if not two_digit_str.startswith('0'):
                two_digit_val = int(two_digit_str)
                if 10 <= two_digit_val <= 26:
                    dp[i] += dp[i-2]

    return dp[n]
