    def parse():
        i = 0
        n = len(expr)

        def peek():
            if i < n:
                return expr[i]
            return None

        def consume():
            nonlocal i
            ch = peek()
            if ch is not None:
                i += 1
            return ch

        def parse_number():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            return int(expr[start:i])

        def parse_term():
            result = parse_factor()
            while peek() in ['+', '-']:
                op = consume()
                right = parse_factor()
                if op == '+':
                    result += right
                else:
                    result -= right
            return result

        def parse_factor():
            ch = peek()
            if ch == '(':
                consume()  # consume '('
                result = parse_term()
                if peek() != ')':
                    raise ValueError("Missing closing parenthesis")
                consume()  # consume ')'
                return result
            elif ch is not None and ch.isdigit():
                return parse_number()
            else:
                raise ValueError(f"Unexpected character: {ch}")

        return parse_term()

    return parse()
